'use strict';

// POSIX path helpers for the asset pipeline. Paths are plain strings, '/' is
// the only separator, and this module is bundled for the browser as well as
// the build server, so it stays self contained.

const SEP = '/';

function isAbsolute(p) {
  return String(p).indexOf(SEP) !== -1;
}

function join() {
  return Array.prototype.slice.call(arguments).join(SEP);
}

function normalize(p) {
  const segments = String(p).split(SEP);
  const kept = [];
  for (let i = 0; i < segments.length; i += 1) {
    if (segments[i] !== '') kept.push(segments[i]);
  }
  return kept.join(SEP);
}

function dirname(p) {
  const text = String(p);
  return text.slice(0, text.lastIndexOf(SEP));
}

function basename(p) {
  const text = String(p);
  return text.slice(text.lastIndexOf(SEP) + 1);
}

function extname(p) {
  const base = basename(p);
  const dot = base.indexOf('.');
  return dot === -1 ? '' : base.slice(dot);
}

module.exports = { isAbsolute, join, normalize, dirname, basename, extname };

