'use strict';
const test = require('node:test');
const assert = require('node:assert');
const {
  isAbsolute,
  join,
  normalize,
  dirname,
  basename,
  extname,
  relative,
  resolve,
  commonAncestor,
} = require('./src/path.js');

test('s1 absolute detection is about the first character, not any separator', () => {
  assert.strictEqual(isAbsolute('/etc'), true);
  assert.strictEqual(isAbsolute('/'), true);
  assert.strictEqual(isAbsolute('/a/b/c'), true);
  assert.strictEqual(isAbsolute('/usr/local/share/fonts'), true, 'any path that starts at the root is absolute');
  assert.strictEqual(isAbsolute('//shared/assets'), true, 'a doubled leading separator still starts at the root');
  assert.strictEqual(isAbsolute('/var/log'), true);

  assert.strictEqual(isAbsolute('src/index.js'), false, 'a separator in the middle does not make a path absolute');
  assert.strictEqual(isAbsolute('./src'), false);
  assert.strictEqual(isAbsolute('..'), false);
  assert.strictEqual(isAbsolute(''), false);
  assert.strictEqual(isAbsolute('a'), false);
  assert.strictEqual(isAbsolute('vendor/dist/bundle.js'), false);

  for (const junk of [undefined, null, 42, {}, ['/a']]) {
    assert.strictEqual(isAbsolute(junk), false, 'a value that is not a string is not an absolute path');
  }
});

test('s2 join puts exactly one separator between the arguments that survive', () => {
  assert.strictEqual(join('assets/', 'img'), 'assets/img');
  assert.strictEqual(join('assets', '/img'), 'assets/img');
  assert.strictEqual(join('assets/', '/img'), 'assets/img');
  assert.strictEqual(join('assets', 'img'), 'assets/img');
  assert.strictEqual(join('/srv/', 'www'), '/srv/www');
  assert.strictEqual(join('a', 'b', 'c'), 'a/b/c');

  assert.strictEqual(join('assets', '', 'img'), 'assets/img', 'an empty argument is skipped rather than separated');
  assert.strictEqual(join('', 'assets', 'img'), 'assets/img');
  assert.strictEqual(join('assets', 'img', ''), 'assets/img');

  assert.strictEqual(join('assets', 'img/'), 'assets/img/', 'a trailing separator on the last argument is kept');
  assert.strictEqual(join('/srv', 'www/'), '/srv/www/');

  assert.strictEqual(join(), '.');
  assert.strictEqual(join('', ''), '.');
  assert.strictEqual(join('assets', 42, 'img'), 'assets/img', 'an argument that is not a string is skipped');
  assert.strictEqual(join('/'), '/');
  assert.strictEqual(join('/', 'srv'), '/srv');
});

test('s3 normalize collapses separators and resolves dot and dot-dot segments', () => {
  assert.strictEqual(normalize('a/b/./c'), 'a/b/c');
  assert.strictEqual(normalize('a//b'), 'a/b');
  assert.strictEqual(normalize('a///b////c'), 'a/b/c');
  assert.strictEqual(normalize('./a/b'), 'a/b');
  assert.strictEqual(normalize('/x/y/../z'), '/x/z');
  assert.strictEqual(normalize('src/../lib/index.js'), 'lib/index.js');
  assert.strictEqual(normalize('a/b/../../c'), 'c', 'dot-dot cancels against the resolved result');
  assert.strictEqual(normalize('/a/./b/../c/./d'), '/a/c/d');
  assert.strictEqual(normalize('a/b/c'), 'a/b/c', 'a path with nothing to resolve is unchanged');
  assert.strictEqual(normalize('/a/b/c'), '/a/b/c');
});

test('s4 normalize keeps the root, keeps unresolvable dot-dot, and keeps a trailing separator', () => {
  assert.strictEqual(normalize(''), '.');
  assert.strictEqual(normalize('.'), '.');
  assert.strictEqual(normalize('a/..'), '.', 'a path that cancels itself out is the current directory');
  assert.strictEqual(normalize('a/../'), '.', 'and it carries no trailing separator');

  assert.strictEqual(normalize('/'), '/');
  assert.strictEqual(normalize('//'), '/');
  assert.strictEqual(normalize('/..'), '/', 'an absolute path cannot climb above the root');
  assert.strictEqual(normalize('/a/../../b'), '/b');
  assert.strictEqual(normalize('/a/..'), '/');

  assert.strictEqual(normalize('..'), '..', 'a relative path keeps the dot-dot it cannot cancel');
  assert.strictEqual(normalize('../../a'), '../../a');
  assert.strictEqual(normalize('a/../../b'), '../b');
  assert.strictEqual(normalize('../a/../b'), '../b');

  assert.strictEqual(normalize('a/b/'), 'a/b/');
  assert.strictEqual(normalize('/a//b//'), '/a/b/');
  assert.strictEqual(normalize('a/b/../'), 'a/');
  assert.strictEqual(normalize('/a/b/./'), '/a/b/');
});

test('s5 join resolves dot and dot-dot across its arguments', () => {
  assert.strictEqual(join('assets/img', '../css'), 'assets/css');
  assert.strictEqual(join('/srv', '../../etc'), '/etc', 'the root clamp applies across arguments');
  assert.strictEqual(join('a', 'b', '../../c'), 'c');
  assert.strictEqual(join('a/b', './c'), 'a/b/c');
  assert.strictEqual(join('a', '..'), '.');
  assert.strictEqual(join('a', '../..'), '..');
  assert.strictEqual(join('/a', '..'), '/');
  assert.strictEqual(join('/srv//www', 'index.html'), '/srv/www/index.html');
  assert.strictEqual(join('assets', '../img/'), 'img/', 'the trailing separator survives the resolution');
  assert.strictEqual(join('assets/', '', 'img/../css'), 'assets/css');
});

test('s6 dirname answers with the directory the path sits in', () => {
  assert.strictEqual(dirname('/a/b'), '/a');
  assert.strictEqual(dirname('/a'), '/', 'a first-level absolute path keeps its root');
  assert.strictEqual(dirname('a'), '.', 'a path with no separator sits in the current directory');
  assert.strictEqual(dirname('/'), '/');
  assert.strictEqual(dirname('a/b/'), 'a', 'a trailing separator is stripped before the cut');
  assert.strictEqual(dirname(''), '.');
  assert.strictEqual(dirname('/srv/www/index.html'), '/srv/www');
  assert.strictEqual(dirname('assets/img/logo.svg'), 'assets/img');
  assert.strictEqual(dirname('/a//b'), '/a');
  assert.strictEqual(dirname('/a/b/../c.txt'), '/a', 'the cut happens on the normalized path');
  assert.strictEqual(dirname('a/b/c/'), 'a/b');
});

test('s7 basename answers with the last segment whatever the path is spelled like', () => {
  assert.strictEqual(basename('/a/b.txt'), 'b.txt');
  assert.strictEqual(basename('assets/img/'), 'img', 'a trailing separator does not hide the last segment');
  assert.strictEqual(basename('a/b/'), 'b');
  assert.strictEqual(basename('logo.svg'), 'logo.svg');
  assert.strictEqual(basename('/'), '', 'the root has no last segment');
  assert.strictEqual(basename('//'), '');
  assert.strictEqual(basename(''), '.');
  assert.strictEqual(basename('.'), '.');
  assert.strictEqual(basename('/srv/www//'), 'www');
  assert.strictEqual(basename('a/b/../c'), 'c', 'the segment is taken from the normalized path');
});

test('s8 extname works from the last dot and knows a dotfile has no extension', () => {
  assert.strictEqual(extname('archive.tar.gz'), '.gz');
  assert.strictEqual(extname('/srv/www/index.html'), '.html');
  assert.strictEqual(extname('.bashrc'), '', 'a leading dot names the file rather than an extension');
  assert.strictEqual(extname('/home/u/.bashrc'), '');
  assert.strictEqual(extname('.bashrc.bak'), '.bak');
  assert.strictEqual(extname('README'), '');
  assert.strictEqual(extname('notes.'), '.', 'a base ending in a dot has that dot as its extension');
  assert.strictEqual(extname('notes..'), '.');
  assert.strictEqual(extname('.'), '');
  assert.strictEqual(extname('..'), '');
  assert.strictEqual(extname('/'), '');
  assert.strictEqual(extname(''), '');
  assert.strictEqual(extname('assets/img/'), '');
  assert.strictEqual(extname('assets/img.d/logo'), '', 'the extension comes off the base, not off a directory');
  assert.strictEqual(extname('assets/img.d/logo.svg'), '.svg');
});

test('s9 basename strips a suffix it was given, literally and never to nothing', () => {
  assert.strictEqual(basename('/a/b.txt', '.txt'), 'b');
  assert.strictEqual(basename('assets/img/logo.svg', '.svg'), 'logo');
  assert.strictEqual(basename('a/b.tar.gz', '.gz'), 'b.tar');
  assert.strictEqual(basename('a/b.txt', '.md'), 'b.txt', 'a suffix that does not match leaves the base alone');
  assert.strictEqual(basename('a/b.txt', 'txt'), 'b.', 'the suffix is matched as a tail, not as an extension');
  assert.strictEqual(basename('/etc/.txt', '.txt'), '.txt', 'a base that is exactly the suffix is returned whole');
  assert.strictEqual(basename('a/b/', 'b'), 'b');
  assert.strictEqual(basename('a/logo.svg', ''), 'logo.svg');
  assert.strictEqual(basename('a/logo.svg', 42), 'logo.svg');
  assert.strictEqual(basename('a/b.42', 42), 'b.42', 'a suffix that is not a string is ignored, not coerced into one');
  assert.strictEqual(basename('a/logo.svg', null), 'logo.svg');
  assert.strictEqual(basename('a/logo.svg'), 'logo.svg');
  assert.strictEqual(basename('a/img.svg.svg', '.svg'), 'img.svg', 'only one suffix comes off');
});

test('s10 relative walks between two absolute paths', () => {
  assert.strictEqual(relative('/a/b/c', '/a/b/d'), '../d');
  assert.strictEqual(relative('/a/b', '/a/b/c/d'), 'c/d');
  assert.strictEqual(relative('/a/b/c', '/a'), '../..');
  assert.strictEqual(relative('/a/b', '/a/b'), '', 'the same path either side is no walk at all');
  assert.strictEqual(relative('/a/b/', '/a/b'), '');
  assert.strictEqual(relative('/a/bc', '/a/bd'), '../bd', 'segments compare whole, not as text prefixes');
  assert.strictEqual(relative('/srv/www', '/srv/wwwroot/index.html'), '../wwwroot/index.html');
  assert.strictEqual(relative('/', '/a/b'), 'a/b', 'the root is a legitimate start');
  assert.strictEqual(relative('/a/b', '/'), '../..', 'and a legitimate end');
  assert.strictEqual(relative('/a/x/../b', '/a/b/c'), 'c', 'both sides normalize first');
  assert.strictEqual(relative('/a/b/', '/a/c/'), '../c', 'and neither trailing separator reaches the answer');
  assert.strictEqual(relative('/a/b/c/d', '/a/e'), '../../../e');
});

test('s11 relative handles relative paths and refuses the pairs it cannot bridge', () => {
  assert.strictEqual(relative('src/a', 'src/b'), '../b');
  assert.strictEqual(relative('src', 'src/a/b'), 'a/b');
  assert.strictEqual(relative('src/a/b', 'src'), '../..');
  assert.strictEqual(relative('a', 'a'), '');
  assert.strictEqual(relative('', 'a/b'), 'a/b', 'the current directory is a legitimate start');
  assert.strictEqual(relative('a/b', '.'), '../..');
  assert.strictEqual(relative('../src/a', '../src/b'), '../b', 'equal leading dot-dot cancel each other');
  assert.strictEqual(relative('..', '../a'), 'a');
  assert.strictEqual(relative('../a', '..'), '..');

  assert.strictEqual(relative('/a/b', 'a/b'), null, 'an absolute path and a relative one cannot be bridged');
  assert.strictEqual(relative('a/b', '/a/b'), null);
  assert.strictEqual(relative('..', 'src/a'), null, 'unequal leading dot-dot cannot be bridged');
  assert.strictEqual(relative('src/a', '..'), null);
  assert.strictEqual(relative('../..', '../a'), null);

  for (const junk of [undefined, null, 42, {}, ['/a']]) {
    assert.strictEqual(relative(junk, '/a/b'), null, 'a value that is not a string cannot be walked');
    assert.strictEqual(relative('/a/b', junk), null);
  }
});

test('s12 resolve reads its arguments from the right and stops at an absolute one', () => {
  assert.strictEqual(resolve('/srv/www', 'index.html'), '/srv/www/index.html');
  assert.strictEqual(resolve('/srv/www', '/etc', 'hosts'), '/etc/hosts', 'an absolute argument discards what is left of it');
  assert.strictEqual(resolve('/srv/www', '..'), '/srv');
  assert.strictEqual(resolve('src', '../lib', 'index.js'), 'lib/index.js', 'with nothing absolute the answer is relative');
  assert.strictEqual(resolve('a', 'b'), 'a/b');
  assert.strictEqual(resolve(), '.');
  assert.strictEqual(resolve('', ''), '.');
  assert.strictEqual(resolve('a', 42, 'b'), 'a/b');
  assert.strictEqual(resolve('/srv/www/'), '/srv/www', 'resolve never keeps a trailing separator');
  assert.strictEqual(resolve('/srv', 'www/'), '/srv/www');
  assert.strictEqual(join('/srv', 'www/'), '/srv/www/', 'which is exactly where it differs from join');
  assert.strictEqual(resolve('/'), '/');
  assert.strictEqual(resolve('/a', '..'), '/');
  assert.strictEqual(resolve('a', '..'), '.');
  assert.strictEqual(resolve('/srv', '', 'www', '', 'index.html'), '/srv/www/index.html');
  assert.strictEqual(resolve('assets', '/srv/www/', 'img/'), '/srv/www/img');
});

test('s13 commonAncestor finds the deepest path every entry sits under', () => {
  assert.strictEqual(commonAncestor(['/srv/a/one', '/srv/a/two']), '/srv/a');
  assert.strictEqual(commonAncestor(['/srv/ab', '/srv/ac']), '/srv', 'segments compare whole, not as text prefixes');
  assert.strictEqual(commonAncestor(['/srv/a/one']), '/srv/a/one', 'a single entry is its own ancestor');
  assert.strictEqual(commonAncestor(['/srv/a/one', '/srv/a/one/two/three']), '/srv/a/one');
  assert.strictEqual(commonAncestor(['/srv/a', '/etc/b']), '/', 'absolute entries always share the root');
  assert.strictEqual(commonAncestor(['/a', '/a/b', '/a/c/d']), '/a');
  assert.strictEqual(commonAncestor(['/srv/a/', '/srv/a']), '/srv/a', 'a trailing separator makes no difference');
  assert.strictEqual(commonAncestor(['/srv/./a/one', '/srv/x/../a/two']), '/srv/a', 'entries normalize first');

  assert.strictEqual(commonAncestor(['src/a', 'src/b']), 'src');
  assert.strictEqual(commonAncestor(['src/a', 'lib/b']), '.', 'relative entries that share nothing share the current directory');
  assert.strictEqual(commonAncestor(['../src/a', '../src/b']), '../src');

  assert.strictEqual(commonAncestor([]), null);
  assert.strictEqual(commonAncestor('/srv/a'), null, 'the argument is an array of paths');
  assert.strictEqual(commonAncestor(null), null);
  assert.strictEqual(commonAncestor(['/srv/a', 42]), null);
  assert.strictEqual(commonAncestor(['/srv/a', 'srv/b']), null, 'absolute and relative entries cannot be mixed');
  assert.strictEqual(commonAncestor(['../src/a', 'src/b']), null, 'nor can unequal leading dot-dot');
});

