'use strict';

// POSIX path helpers for the asset pipeline. Paths are plain strings, '/' is
// the only separator, and this module is bundled for the browser as well as
// the build server, so it stays self contained.

const SEP = '/';

function isAbsolute(p) {
  return typeof p === 'string' && p.charAt(0) === SEP;
}

// At most one trailing separator survives normalize, and the root keeps its
// own.
function stripTrailing(text) {
  let end = text.length;
  while (end > 1 && text.charAt(end - 1) === SEP) end -= 1;
  return text.slice(0, end);
}

// The meaningful segments of a path: empties and '.' drop out, and '..'
// cancels whatever it resolved on to rather than whatever was written before
// it. A leading '..' survives on a relative path because nothing above it is
// known; on an absolute path it falls off the root.
function segmentsOf(text, absolute) {
  const out = [];
  const parts = text.split(SEP);
  for (let i = 0; i < parts.length; i += 1) {
    const seg = parts[i];
    if (seg === '' || seg === '.') continue;
    if (seg === '..') {
      if (out.length > 0 && out[out.length - 1] !== '..') out.pop();
      else if (!absolute) out.push('..');
      continue;
    }
    out.push(seg);
  }
  return out;
}

function leadingUps(segments) {
  let n = 0;
  while (n < segments.length && segments[n] === '..') n += 1;
  return n;
}

function normalize(p) {
  const text = typeof p === 'string' ? p : String(p);
  const absolute = isAbsolute(text);
  const segments = segmentsOf(text, absolute);
  if (segments.length === 0) return absolute ? SEP : '.';
  const trailing = text.charAt(text.length - 1) === SEP;
  return (absolute ? SEP : '') + segments.join(SEP) + (trailing ? SEP : '');
}

function join() {
  const parts = [];
  for (let i = 0; i < arguments.length; i += 1) {
    const part = arguments[i];
    if (typeof part === 'string' && part !== '') parts.push(part);
  }
  if (parts.length === 0) return '.';
  return normalize(parts.join(SEP));
}

function dirname(p) {
  const text = stripTrailing(normalize(p));
  if (text === SEP) return SEP;
  const cut = text.lastIndexOf(SEP);
  if (cut === -1) return '.';
  if (cut === 0) return SEP;
  return text.slice(0, cut);
}

function basename(p, suffix) {
  const text = stripTrailing(normalize(p));
  const base = text === SEP ? '' : text.slice(text.lastIndexOf(SEP) + 1);
  if (typeof suffix !== 'string' || suffix === '') return base;
  if (base === suffix || !base.endsWith(suffix)) return base;
  return base.slice(0, base.length - suffix.length);
}

function extname(p) {
  const base = basename(p);
  if (base === '.' || base === '..') return '';
  const dot = base.lastIndexOf('.');
  if (dot <= 0) return '';
  return base.slice(dot);
}

function relative(from, to) {
  if (typeof from !== 'string' || typeof to !== 'string') return null;
  const absolute = isAbsolute(from);
  if (absolute !== isAbsolute(to)) return null;
  const a = segmentsOf(from, absolute);
  const b = segmentsOf(to, absolute);
  // Two relative paths can only be walked between when they start from the
  // same place; the name of the directory below a '..' is in neither string.
  if (!absolute && leadingUps(a) !== leadingUps(b)) return null;
  let shared = 0;
  while (shared < a.length && shared < b.length && a[shared] === b[shared]) shared += 1;
  const hops = [];
  for (let i = shared; i < a.length; i += 1) hops.push('..');
  return hops.concat(b.slice(shared)).join(SEP);
}

function resolve() {
  let acc = '';
  for (let i = arguments.length - 1; i >= 0; i -= 1) {
    const part = arguments[i];
    if (typeof part !== 'string' || part === '') continue;
    acc = acc === '' ? part : part + SEP + acc;
    if (isAbsolute(part)) break;
  }
  if (acc === '') return '.';
  return stripTrailing(normalize(acc));
}

function commonAncestor(paths) {
  if (!Array.isArray(paths) || paths.length === 0) return null;
  let absolute = false;
  let ups = 0;
  let shared = null;
  for (let i = 0; i < paths.length; i += 1) {
    const entry = paths[i];
    if (typeof entry !== 'string') return null;
    const abs = isAbsolute(entry);
    const segments = segmentsOf(entry, abs);
    if (shared === null) {
      absolute = abs;
      ups = leadingUps(segments);
      shared = segments;
      continue;
    }
    if (abs !== absolute) return null;
    if (!absolute && leadingUps(segments) !== ups) return null;
    let n = 0;
    while (n < shared.length && n < segments.length && shared[n] === segments[n]) n += 1;
    shared = shared.slice(0, n);
  }
  if (shared.length === 0) return absolute ? SEP : '.';
  return (absolute ? SEP : '') + shared.join(SEP);
}

module.exports = {
  isAbsolute,
  join,
  normalize,
  dirname,
  basename,
  extname,
  relative,
  resolve,
  commonAncestor,
};
